{
  "concepts": [],
  "definitions": [
    {
      "term": {
        "text": "Math class",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "The Math class is defined in the java.lang package, is always available without explicit import, and provides a collection of static methods for performing mathematical operations.",
        "refs": ["Q0001"]
      },
      "context": null
    },
    {
      "term": {
        "text": "round method",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "The round method rounds a floating‑point number to the nearest whole number; it is overloaded: one version takes a float and returns an int, another takes a double and returns a long.",
        "refs": ["Q0001", "Q0002"]
      },
      "context": null
    },
    {
      "term": {
        "text": "ceil method",
        "refs": ["Q0002"]
      },
      "definition_text": {
        "text": "The ceil method returns the smallest integer that is greater than or equal to the given number; it returns a double value.",
        "refs": ["Q0002"]
      },
      "context": null
    },
    {
      "term": {
        "text": "floor method",
        "refs": ["Q0003"]
      },
      "definition_text": {
        "text": "The floor method returns the largest integer that is less than or equal to the given number; it returns a double value.",
        "refs": ["Q0003"]
      },
      "context": null
    },
    {
      "term": {
        "text": "max method",
        "refs": ["Q0003"]
      },
      "definition_text": {
        "text": "The max method returns the greater of two values; it is overloaded for int, long, float, and double arguments.",
        "refs": ["Q0003"]
      },
      "context": null
    },
    {
      "term": {
        "text": "min method",
        "refs": ["Q0004"]
      },
      "definition_text": {
        "text": "The min method returns the smaller of two values; it is overloaded for various primitive numeric types.",
        "refs": ["Q0004"]
      },
      "context": null
    },
    {
      "term": {
        "text": "random method",
        "refs": ["Q0004"]
      },
      "definition_text": {
        "text": "The random method returns a double value uniformly distributed between 0.0 (inclusive) and 1.0 (exclusive).",
        "refs": ["Q0004"]
      },
      "context": null
    }
  ],
  "examples": [
    {
      "exemplifies": {
        "text": "round",
        "refs": ["Q0001"]
      },
      "example_text": {
        "text": "Passing 1.1 as a float to Math.round and storing the result in an int yields 1.",
        "refs": ["Q0001"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "ceil",
        "refs": ["Q0002"]
      },
      "example_text": {
        "text": "Math.ceil(1.1) returns 2 (after casting to int).",
        "refs": ["Q0002"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "floor",
        "refs": ["Q0003"]
      },
      "example_text": {
        "text": "Math.floor(1.1) returns 1 (after casting to int).",
        "refs": ["Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "max",
        "refs": ["Q0003"]
      },
      "example_text": {
        "text": "Math.max(1, 2) returns 2.",
        "refs": ["Q0003"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "min",
        "refs": ["Q0004"]
      },
      "example_text": {
        "text": "Math.min(1, 2) returns 1.",
        "refs": ["Q0004"]
      },
      "example_type": null
    },
    {
      "exemplifies": {
        "text": "random",
        "refs": ["Q0004"]
      },
      "example_text": {
        "text": "Math.random() returns a double between 0 and 1; multiplying by 100 yields a value between 0 and 100.",
        "refs": ["Q0004", "Q0005"]
      },
      "example_type": null
    }
  ],
  "explanations": [],
  "facts": [
    {
      "fact_text": {
        "text": "Math class methods are static and can be accessed without creating an instance of Math.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Attempting to store the result of Math.ceil (which returns double) directly into an int causes a compilation error; explicit casting is required.",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "Math.random() returns a double; assigning it to an int without casting causes a compilation error.",
        "refs": ["Q0004"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [],
  "relationships": [],
  "excluded": []
}
